'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var randu = require( '@stdlib/random/base/randu' );
var round = require( '@stdlib/math/base/special/round' );
var powf = require( '@stdlib/math/base/special/powf' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var real = require( '@stdlib/complex/float32/real' );
var imag = require( '@stdlib/complex/float32/imag' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var cfloornf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( cfloornf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cfloornf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a `NaN` if provided a `NaN`', opts, function test( t ) {
	var v;

	v = cfloornf( new Complex64( NaN, NaN ), 0 );
	t.strictEqual( isnanf( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imag( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-0` if provided `-0`', opts, function test( t ) {
	var v;

	v = cfloornf( new Complex64( -0.0, -0.0 ), 0 );
	t.strictEqual( isNegativeZerof( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imag( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( -0.0, -0.0 ), -2 );
	t.strictEqual( isNegativeZerof( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imag( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( -0.0, -0.0 ), 2 );
	t.strictEqual( isNegativeZerof( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imag( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+0` if provided `+0`', opts, function test( t ) {
	var v;

	v = cfloornf( new Complex64( +0.0, +0.0 ), 0 );
	t.strictEqual( isPositiveZerof( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imag( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( +0.0, +0.0 ), -2 );
	t.strictEqual( isPositiveZerof( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imag( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( +0.0, +0.0 ), 2 );
	t.strictEqual( isPositiveZerof( real( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imag( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports rounding real and imaginary components to a desired number of decimals', opts, function test( t ) {
	var v;

	v = cfloornf( new Complex64( -3.141592653589793, 3.141592653589793 ), -2 );
	t.strictEqual( isAlmostSameValue( real( v ), f32( -3.15 ), 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( imag( v ), f32( 3.14 ), 1 ), true, 'returns expected value' );

	v = cfloornf( new Complex64( 3.141592653589793, -3.141592653589793 ), -2 );
	t.strictEqual( isAlmostSameValue( real( v ), f32( 3.14 ), 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( imag( v ), f32( -3.15 ), 1 ), true, 'returns expected value' );

	v = cfloornf( new Complex64( 9.99999, 9.99999 ), -2 );
	t.strictEqual( isAlmostSameValue( real( v ), f32( 9.99 ), 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( imag( v ), f32( 9.99 ), 1 ), true, 'returns expected value' );

	v = cfloornf( new Complex64( 0.0, 0.0 ), 2 );
	t.strictEqual( real( v ), 0.0, 'returns expected value' );
	t.strictEqual( imag( v ), 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports rounding components to a desired number of digits', opts, function test( t ) {
	var v;

	v = cfloornf( new Complex64( -1234.0, 1234.0 ), 2 );
	t.strictEqual( isAlmostSameValue( real( v ), -1300.0, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostSameValue( imag( v ), 1200.0, 1 ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the components unchanged if provided an `n` which is less than the minimum decimal exponential (-45)', opts, function test( t ) {
	var exp;
	var n;
	var x;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		exp = round( randu()*76.0 ) - 38;
		x = f32( (1.0+randu()) * powf( 10.0, exp ) );
		n = -(round( randu()*100.0 ) + 46);
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( real( v ), x, 'returns expected value' );
		t.strictEqual( imag( v ), x, 'returns expected value' );
	}
	t.end();
});

tape( 'if a component is too large a float to have decimals and `n < 0`, the component is returned unchanged', opts, function test( t ) {
	var sign;
	var exp;
	var x;
	var n;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		sign = ( randu()<0.5 ) ? -1.0 : 1.0;
		exp = 8 + round( randu()*30.0 );
		x = f32( sign * (1.0+randu()) * powf( 10.0, exp ) );
		n = -( round( randu()*38.0) );
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( real( v ), x, ' returns expected value' );
		t.strictEqual( imag( v ), x, ' returns expected value' );
	}
	t.end();
});

tape( 'if `n > 38` and a component is less than zero, the function returns `-infinity`', opts, function test( t ) {
	var exp;
	var x;
	var n;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		exp = round( randu()*37.0 );
		x = f32( -(1.0+randu()) * powf( 10.0, exp ) );
		n = round( randu()*10.0 ) + 39;
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( real( v ), NINF, ' returns -infinity' );
		t.strictEqual( imag( v ), NINF, ' returns -infinity' );
	}
	t.end();
});

tape( 'if `n > 38` and a component is greater than or equal to zero, the function returns `+0` (sign preserving)', opts, function test( t ) {
	var exp;
	var x;
	var n;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		exp = round( randu()*37.0 );
		x = f32( (1.0+randu()) * powf( 10.0, exp ) );
		n = round( randu()*10.0 ) + 39;
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( isPositiveZerof( real( v ) ), true, ' returns +0' );
		t.strictEqual( isPositiveZerof( imag( v ) ), true, ' returns +0' );
	}
	t.end();
});

tape( 'if the function encounters overflow, the function returns the input component', opts, function test( t ) {
	var x;
	var v;

	x = f32( 3.14 );
	v = cfloornf( new Complex64( x, x ), -46 );
	t.strictEqual( real( v ), x, 'returns expected value' );
	t.strictEqual( imag( v ), x, 'returns expected value' );

	x = f32( -3.14 );
	v = cfloornf( new Complex64( x, x ), -46 );
	t.strictEqual( real( v ), x, 'returns expected value' );
	t.strictEqual( imag( v ), x, 'returns expected value' );

	x = f32( 16777216.0 );
	v = cfloornf( new Complex64( x, x ), -40 );
	t.strictEqual( real( v ), x, 'returns expected value' );
	t.strictEqual( imag( v ), x, 'returns expected value' );

	x = f32( -16777216.0 );
	v = cfloornf( new Complex64( x, x ), -40 );
	t.strictEqual( real( v ), x, 'returns expected value' );
	t.strictEqual( imag( v ), x, 'returns expected value' );

	t.end();
});
